async function request(path,{method='GET',body,token,prefer,auth=false}={}){if(localDemo)throw Error('Mode démonstration : aucun accès au serveur.');const headers={apikey:KEY,'Content-Type':'application/json'};if(token)headers.Authorization='Bearer '+token;if(prefer)headers.Prefer=prefer;const r=await fetch(BASE+path,{method,headers,body:body===undefined?undefined:JSON.stringify(body),cache:'no-store',signal:AbortSignal.timeout(20000)});const txt=await r.text();let j;try{j=txt?JSON.parse(txt):null}catch{j=txt}if(!r.ok){const raw=j?.message||j?.msg||j?.error_description||j?.error||'';const msg=({invalid_credentials:'Adresse e-mail ou mot de passe incorrect.',email_not_confirmed:'Adresse e-mail non confirmée.',over_request_rate_limit:'Trop de requêtes. Réessaie plus tard.',PGRST301:'Session expirée.',42501:'Accès refusé.'})[j?.code]||(/Invalid login credentials/i.test(raw)?'Adresse e-mail ou mot de passe incorrect.':(/[àâçéèêëîïôùûüœ]/i.test(raw)||j?.code==='P0001')?raw:'Erreur du serveur (HTTP '+r.status+(j?.code?' · '+j.code:'')+').');if(raw)console.warn('Supabase :',raw);const e=new Error(msg);e.status=r.status;e.code=j?.code;throw e}return j}
async function auth(path,body){return request('/auth/v1/'+path,{method:'POST',body})}
