async function token(){if(localDemo)throw Error('Mode démonstration : aucun jeton serveur.');if(!session)throw Error('Connexion requise');const refresh=async()=>{const saved=read(sessionKey,null);if(!saved||saved.user.id!==session.user.id)throw Error('Session modifiée dans un autre onglet');session=saved;if(session.expires_at>Date.now()/1000+60)return session.access_token;const j=await auth('token?grant_type=refresh_token',{refresh_token:session.refresh_token});if(j.user.id!==session.user.id)throw Error('Identité inattendue');storeSession({...j,expires_at:j.expires_at||Math.floor(Date.now()/1000)+(j.expires_in||3600)});return session.access_token};return navigator.locks?navigator.locks.request(prefix+'refresh',refresh):refresh()}
