 if(guided){fixture.estimates.push(...awayPlayers.map(q=>({matchup_id:mid,own_team_id:own,opponent_team_id:away,player_id:captain.id,opponent_player_id:q.id,estimate:window.TMTDemoCaptainExample[q.display_order],updated_at:'2026-01-01T00:00:00Z'})));write(prefix+'pairing09:'+session.user.id+':'+mid,null);}
